/* Minimal Phaser stub for tileAd2 scaffold packing — replace with real Phaser for production. */
window.Phaser = window.Phaser || {
  AUTO: 0,
  Scale: { RESIZE: 3, CENTER_BOTH: 1 },
  Game: function (config) {
    this.config = config;
    this.scale = {
      resize: function () {}
    };
    var scene = config && config.scene;
    var self = this;
    this.scene = { scenes: [{ cameras: { main: { width: window.innerWidth, height: window.innerHeight } }, add: {}, textures: { exists: function () { return false; } }, input: {} }] };
    setTimeout(function () {
      if (scene && typeof scene.preload === 'function') scene.preload.call(self.scene.scenes[0]);
      if (scene && typeof scene.create === 'function') scene.create.call(self.scene.scenes[0]);
    }, 0);
  }
};
